                ast.Mult: op.mul,
                ast.Div: op.truediv,
                ast.Pow: op.pow,
                ast.USub: op.neg,
                ast.UAdd: op.pos,
            }

            class SafeEval:
                def _eval(self, node):
                    if isinstance(node, ast.Num):
                        return node.n
                    elif isinstance(node, ast.Constant):
                        return node.value
                    elif isinstance(node, ast.BinOp):
                        left = self._eval(node.left)
                        right = self._eval(node.right)
                        return allowed_ops[type(node.op)](left, right)
                    elif isinstance(node, ast.UnaryOp):
                        return allowed_ops[type(node.op)](self._eval(node.operand))
                    else:
                        raise ValueError(f"Unsafe node: {type(node).__name__}")

            evaluator = SafeEval()
            return evaluator._eval(tree.body) == 24
        except:
            return False
